alter table public.profiles enable row level security;alter table public.service_categories enable row level security;alter table public.service_centres enable row level security;alter table public.centre_services enable row level security;alter table public.centre_capabilities enable row level security;alter table public.centre_photos enable row level security;alter table public.verifications enable row level security;alter table public.enquiries enable row level security;alter table public.reviews enable row level security;alter table public.routes enable row level security;alter table public.route_stops enable row level security;alter table public.events enable row level security;alter table public.event_registrations enable row level security;alter table public.posts enable row level security;alter table public.comments enable row level security;alter table public.reports enable row level security;
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create policy "public active centres" on public.service_centres for select using(is_active=true);
create policy "public categories" on public.service_categories for select using(true);
create policy "public centre services" on public.centre_services for select using(true);create policy "public centre capabilities" on public.centre_capabilities for select using(true);create policy "public centre photos" on public.centre_photos for select using(true);
create policy "partners update own centres" on public.service_centres for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "partners insert own centres" on public.service_centres for insert with check(owner_id=auth.uid());
create policy "public submit enquiry" on public.enquiries for insert with check(length(name)>1 and length(phone)>=8 and length(service_need)>4);
create policy "partners see own enquiries" on public.enquiries for select using(exists(select 1 from public.service_centres c where c.id=centre_id and c.owner_id=auth.uid()) or public.current_role() in ('moderator','admin'));
create policy "public published reviews" on public.reviews for select using(status='published');create policy "public submit reviews" on public.reviews for insert with check(overall_rating between 1 and 5);
create policy "public published routes" on public.routes for select using(status='published');create policy "public route stops" on public.route_stops for select using(exists(select 1 from public.routes r where r.id=route_id and r.status='published'));
create policy "public published events" on public.events for select using(status='published');create policy "public event registration" on public.event_registrations for insert with check(length(name)>1 and length(phone)>=8);
create policy "public published posts" on public.posts for select using(status='published');create policy "public published comments" on public.comments for select using(status='published');create policy "public comment submission" on public.comments for insert with check(length(display_name)>1 and length(body)>2);
create policy "public report submission" on public.reports for insert with check(length(reason)>3);
create policy "profiles own read" on public.profiles for select using(id=auth.uid() or public.current_role() in ('moderator','admin'));create policy "profiles own update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "admin manage categories" on public.service_categories for all using(public.current_role()='admin') with check(public.current_role()='admin');create policy "admin manage content" on public.posts for all using(public.current_role() in ('moderator','admin')) with check(public.current_role() in ('moderator','admin'));create policy "admin manage routes" on public.routes for all using(public.current_role() in ('moderator','admin')) with check(public.current_role() in ('moderator','admin'));create policy "admin manage events" on public.events for all using(public.current_role() in ('moderator','admin')) with check(public.current_role() in ('moderator','admin'));create policy "admin manage reports" on public.reports for select using(public.current_role() in ('moderator','admin'));
